from fractions import Fraction as F
import json

H = F(1, 2)
# Each curve: Laurent polynomials in t = e^s; x,y carry a factor tau, u a factor tau^2.
opts = {
    1: ({1: F(3), 0: F(-3)}, {-1: H, 0: H}, {-2: F(1)}),
    2: ({1: F(2), 0: F(-2)}, {2: F(2), 0: F(-1)}, {0: H, -2: H}),
    3: ({1: F(2), 0: F(-2)}, {1: H, 0: H}, {2: F(1)}),
    4: ({-1: F(1), 0: F(-1)}, {-1: F(-2), 0: F(3)}, {-2: F(2), 0: F(-1)}),
}

def ev(d, t):
    return sum(c * t**k for k, c in d.items())

def ds(d):  # d/ds with t = e^s
    return {k: c * k for k, c in d.items()}

tau = F(3)
ts = [F(1), F(2), F(3), F(1, 2), F(5, 3)]
ok = []
ev_log = {}
for n, (X, Y, U) in opts.items():
    good = True
    # initial curve at s=0 (t=1): x=0, y=tau, u=tau^2
    if ev(X, F(1)) * tau != 0 or ev(Y, F(1)) * tau != tau or ev(U, F(1)) * tau**2 != tau**2:
        good = False
    # Charpit: x_s = F_p = q, y_s = F_q = p, u_s = p q' + q y' = 2pq, with pq = u
    for t in ts:
        xs = ev(ds(X), t) * tau
        ys = ev(ds(Y), t) * tau
        u = ev(U, t) * tau**2
        us = ev(ds(U), t) * tau**2
        q, p = xs, ys
        if p * q != u:
            good = False
        if us != p * xs + q * ys:
            good = False
    # initial compatibility: q = u_tau/y_tau = 2 tau, p = u/q = tau/2
    q0 = ev(ds(X), F(1)) * tau
    p0 = ev(ds(Y), F(1)) * tau
    if q0 != 2 * tau or p0 != tau / 2:
        good = False
    ev_log[n] = good
    if good:
        ok.append(n)

if len(ok) == 1:
    print(json.dumps({"final_answer": "Option %d" % ok[0], "evidence": {"checks": ev_log,
          "derived": "p0=tau/2,q0=2tau; x=2tau(e^s-1), y=tau/2(e^s+1), u=tau^2 e^{2s}"}}))
else:
    print("UNSUPPORTED")
