from fractions import Fraction as Fr

# Charpit by hand: F = p*q - u.
# dx/ds = q, dy/ds = p, du/ds = 2pq = 2u, dp/ds = p, dq/ds = q.
# At s=0: x=0, y=t, u=t^2. Compatibility: u_t = p*x_t + q*y_t -> 2t = q, p = u/q = t/2.
# So x = 2t(e^s-1), y = (t/2)(e^s+1), u = t^2 e^{2s}  (option 3).

# Each option: function (t, E) -> partials (x_t,x_s,y_t,y_s,u_t,u_s,u), with E=e^s
# (option 4 uses F=e^{-s}); s-derivatives are computed exactly by hand.
def opt1(t, E):
    return (3*(E-1), 3*t*E, (1/E+1)/2, -t/(2*E), 2*t/E**2, -2*t*t/E**2, t*t/E**2)

def opt2(t, E):
    return (2*(E-1), 2*t*E, 2*E**2-1, 4*t*E**2, t*(1+1/E**2), -t*t/E**2, t*t/2*(1+1/E**2))

def opt3(t, E):
    return (2*(E-1), 2*t*E, (E+1)/2, t*E/2, 2*t*E**2, 2*t*t*E**2, t*t*E**2)

def opt4(t, F):  # F = e^{-s}, dF/ds = -F
    return (F-1, -t*F, -2*(F-Fr(3, 2)), 2*t*F, 2*t*(2*F**2-1), -4*t*t*F**2, t*t*(2*F**2-1))

def check(opt):
    ok = True
    n = 0
    for t in [Fr(1), Fr(2), Fr(-3), Fr(1, 2), Fr(5)]:
        for E in [Fr(1, 2), Fr(2), Fr(3), Fr(5, 2), Fr(7)]:
            xt, xs, yt, ys, ut, us, u = opt(t, E)
            det = xt*ys - xs*yt
            if det == 0:
                continue
            # solve u_t = p x_t + q y_t ; u_s = p x_s + q y_s
            p = (ut*ys - yt*us) / det
            q = (xt*us - xs*ut) / det
            n += 1
            if p*q != u:
                ok = False
    return ok, n

def init_ok(which):
    # at s=0 (E=1 or F=1): x=0, y=t, u=t^2 ?
    t = Fr(3)
    if which == 1:
        x, y, u = 3*t*(1-1), t/2*(1+1), t*t
    elif which == 2:
        x, y, u = 0, t*(2-1), t*t/2*2
    elif which == 3:
        x, y, u = 0, t/2*2, t*t
    else:
        x, y, u = 0, -2*t*(1-Fr(3, 2)), t*t*(2-1)
    return x == 0 and y == t and u == t*t

results = {}
for i, o in enumerate([opt1, opt2, opt3, opt4], 1):
    ok, n = check(o)
    results[i] = ok
    print(f"Option {i}: initial curve ok={init_ok(i)}, p*q==u on all {n} exact test points: {ok}")

print("Submitted answer is option 1")
print("Derived correct: x=2t(e^s-1), y=(t/2)(e^s+1), u=t^2 e^{2s} (option 3)")
if results[1]:
    print("CHECK PASS")
else:
    print("Option 1 fails pq=u (counterexample found among exact test points)")
    print("CHECK FAIL")
