2) leather iranian box (93) repulsive gray ring (94) ethiopian knife (95) brown bag (96) midsize circular chair (97) snorkeling trash can (98) new whittling fire extinguisher"""

cats = {
 "opinion": "silly terrible wonderful lovely repulsive ridiculous nice awful good mysterious",
 "size": "medium-size massive little large huge tiny big small enormous midsize normal-size",
 "age": "new archaic old-fashioned ancient brand-new old",
 "shape": "rectangular square circular pyramidal triangular spherical prismlike",
 "color": "yellow violet aqua crimson brown green maroon magenta cyan pink blue indigo red gray white black",
 "origin": "egyptian chinese turkish vietnamese german bangladeshi mexican iranian ethiopian russian filipino indonesian thai",
 "material": "plastic wood wool iron fiberglass cardboard glass leather paper cloth",
 "purpose": "typing whittling walking smoking hiking drinking snorkeling exercise driving eating",
}
w2c = {}
for c, ws in cats.items():
    for w in ws.split():
        w2c[w] = c
names = list(cats)

def parse(s):
    toks = s.split()
    i = 0
    while i < len(toks) and toks[i] in w2c:
        i += 1
    return [w2c[t] for t in toks[:i]], toks[i:]

