before = {(a, b): False for a in names for b in names}
for s in sents:
    cs, noun = parse(s)
    if not noun:
        print("UNSUPPORTED"); raise SystemExit
    for i in range(len(cs)):
        for j in range(i + 1, len(cs)):
            if cs[i] == cs[j]:
                continue
            before[(cs[i], cs[j])] = True
for k in names:
    for a in names:
        for b in names:
            if before[(a, k)] and before[(k, b)]:
                before[(a, b)] = True
if any(before[(c, c)] for c in names):
    print("UNSUPPORTED"); raise SystemExit

opts = {
"A": "circular large old-fashioned driving good black sofa",
"B": "wood filipino ancient smoking awful violet tiny prismlike fork",
"C": "prismlike brand-new smoking ridiculous violet iranian paper bed",
"D": "old drinking terrible white normal-size square wrench",
"E": "cloth thai brand-new eating good blue plate",
"F": "fiberglass indonesian brand-new smoking wonderful cyan massive bottle",
"G": "big rectangular archaic smoking terrible yellow vase",
"H": "thai old drinking nice green massive pyramidal clock",
"I": "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
"J": "spherical little ancient walking good indigo bangladeshi jar",
}
correct = []
unknown = False
ev = {}
for L, s in opts.items():
    cs, noun = parse(s)
    if len(noun) != 1 and not noun:
        unknown = True
    ok = True
    for i in range(len(cs) - 1):
        a, b = cs[i], cs[i + 1]
        if a != b and before[(a, b)] and not before[(b, a)]:
            continue
        if a != b and before[(b, a)]:
            ok = False
        else:
            unknown = True
            ok = False
    ev[L] = [ok, cs]
    if ok:
        correct.append(L)
if unknown and False:
    pass
# Determine whether undetermined pairs affected a verdict
undetermined = False
for L, (ok, cs) in ev.items():
    if ok:
        continue
    has_reverse = any(a != b and before[(b, a)] for a, b in zip(cs, cs[1:]))
    if not has_reverse:
        undetermined = True
if undetermined:
    print("UNSUPPORTED")
else:
    ans = "".join(correct) if correct else "K"
    print(json.dumps({"final_answer": ans, "evidence": {L: v[0] for L, v in ev.items()}}))
